window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-18d107dda18df04e"]={"versions": [{"id": "FIG-18d107dda18df04e", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition eines Mode-Switch-Interface im Kontext der AUTOSAR Classic Platform (SWS RTE / MSR SWC). Es modelliert die Einbettung von Modedeklarationen in Sender-Receiver-Schnittstellen auf M1/M2-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>PortInterface::SenderReceiverInterface</code> (Spezialisierung von <code>PortInterface</code>): Kapselt Schnittstellenelemente.\n<ul class=\"fig-list\"><li>Komposition <code>+dataElement</code> (0..*) zu <code>PortInterface::DataElementPrototype</code> (Spezialisierung von <code>DataPrototype</code>) mit Attribut <code>+isQueued: Boolean</code>. Rückreferenz <code>+interface</code> (1).\n</li><li>Komposition <code>+modeGroup</code> (0..*) zu <code>PortInterface::ModeDeclarationGroupPrototype</code> (Spezialisierung von <code>Identifiable</code>). Rückreferenz <code>+interface</code> (1).\n</li></ul>\n</li><li><code>PortInterface::ModeDeclarationGroupPrototype</code>: Verweist über Assoziation <code>«isOfType» +type</code> auf <code>ModeDeclarationGroup</code>.\n</li><li><code>ModeDeclarationGroup</code> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Komposition <code>+modeDeclaration</code> (1..*) zu <code>ModeDeclaration</code> (Spezialisierung von <code>Identifiable</code>).\n</li><li>Gerichtete Assoziation <code>+initialMode</code> mit Kardinalität 1 zu genau einer Instanz von <code>ModeDeclaration</code>.\n</li></ul>\n</li><li><code>ModeDeclaration</code>: Einzelner Modus innerhalb der Modegruppe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenz- oder Zustandsübergangsdarstellung. Es definiert die statischen Typbeziehungen für das spätere Umschalten von Modi zur Laufzeit über RTE-Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein <code>SenderReceiverInterface</code> kann parallel sowohl reguläre Daten- (<code>DataElementPrototype</code>) als auch Modus-Prototypen (<code>ModeDeclarationGroupPrototype</code>) beinhalten.\n</li><li>Jede <code>ModeDeclarationGroup</code> erfordert zwingend mindestens einen Modus (<code>1..*</code>) sowie genau einen initialen Modus (<code>+initialMode: 1</code>).\n</li><li>Der Moduswechsel-Mechanismus stützt sich auf das Typ-Prototyp-Muster: Der Prototyp verweist typisierend (<code>«isOfType»</code>) auf die wiederverwendbare <code>ModeDeclarationGroup</code>.\n</li></ul>"}, {"id": "FIG-5b08290cd5ffe402", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition eines Mode-Switch-Interface im Kontext der AUTOSAR Classic Platform (SWS RTE / MSR SWC). Es modelliert die Einbettung von Modedeklarationen in Sender-Receiver-Schnittstellen auf M1/M2-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>PortInterface::SenderReceiverInterface</code> (Spezialisierung von <code>PortInterface</code>): Kapselt Schnittstellenelemente.\n<ul class=\"fig-list\"><li>Komposition <code>+dataElement</code> (0..*) zu <code>PortInterface::DataElementPrototype</code> (Spezialisierung von <code>DataPrototype</code>) mit Attribut <code>+isQueued: Boolean</code>. Rückreferenz <code>+interface</code> (1).\n</li><li>Komposition <code>+modeGroup</code> (0..*) zu <code>PortInterface::ModeDeclarationGroupPrototype</code> (Spezialisierung von <code>Identifiable</code>). Rückreferenz <code>+interface</code> (1).\n</li></ul>\n</li><li><code>PortInterface::ModeDeclarationGroupPrototype</code>: Verweist über Assoziation <code>«isOfType» +type</code> auf <code>ModeDeclarationGroup</code>.\n</li><li><code>ModeDeclarationGroup</code> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Komposition <code>+modeDeclaration</code> (1..*) zu <code>ModeDeclaration</code> (Spezialisierung von <code>Identifiable</code>).\n</li><li>Gerichtete Assoziation <code>+initialMode</code> mit Kardinalität 1 zu genau einer Instanz von <code>ModeDeclaration</code>.\n</li></ul>\n</li><li><code>ModeDeclaration</code>: Einzelner Modus innerhalb der Modegruppe.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenz- oder Zustandsübergangsdarstellung. Es definiert die statischen Typbeziehungen für das spätere Umschalten von Modi zur Laufzeit über RTE-Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein <code>SenderReceiverInterface</code> kann parallel sowohl reguläre Daten- (<code>DataElementPrototype</code>) als auch Modus-Prototypen (<code>ModeDeclarationGroupPrototype</code>) beinhalten.\n</li><li>Jede <code>ModeDeclarationGroup</code> erfordert zwingend mindestens einen Modus (<code>1..*</code>) sowie genau einen initialen Modus (<code>+initialMode: 1</code>).\n</li><li>Der Moduswechsel-Mechanismus stützt sich auf das Typ-Prototyp-Muster: Der Prototyp verweist typisierend (<code>«isOfType»</code>) auf die wiederverwendbare <code>ModeDeclarationGroup</code>.\n</li></ul>"}], "trans": [{"from": "FIG-18d107dda18df04e", "to": "FIG-5b08290cd5ffe402", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
